<?php
include_once PAD.'subs/calendars/_lib/timegrid.php';
function padTimelineRangeCompare($rows,$timezone='UTC',$title='Planned and actual'){
 if(!is_array($rows)||count($rows)>500||!in_array($timezone,DateTimeZone::listIdentifiers(DateTimeZone::ALL_WITH_BC),TRUE))throw new InvalidArgumentException('rangecompare supports 500 rows and an IANA timezone');$seen=[];$entries=[];$lo=INF;$hi=-INF;$zone=new DateTimeZone($timezone);$esc=fn($s)=>htmlspecialchars((string)$s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
 foreach($rows as $r){if(!is_array($r)||!is_scalar($r['id']??NULL)||(string)$r['id']===''||isset($seen[(string)$r['id']]))throw new InvalidArgumentException('rangecompare needs unique stable IDs');$seen[(string)$r['id']]=TRUE;$entry=['id'=>(string)$r['id'],'label'=>is_scalar($r['label']??NULL)?(string)$r['label']:(string)$r['id']];foreach(['planned','actual'] as $kind){$a=$r[$kind.'start']??NULL;$b=$r[$kind.'end']??NULL;if($a===NULL&&$b===NULL){$entry[$kind]=NULL;continue;}if($a===NULL||$b===NULL)throw new InvalidArgumentException('rangecompare interval requires both endpoints');$start=padCalendarInstant($a);$end=padCalendarInstant($b);if($end<$start)throw new InvalidArgumentException('rangecompare interval reversed');$lo=min($lo,$start->getTimestamp());$hi=max($hi,$end->getTimestamp());$entry[$kind]=[$start,$end];}$entries[]=$entry;}
 $h='<section class="pad-rangecompare"><h2>'.$esc($title).'</h2><p>Timezone: '.$esc($timezone).'; planned (blue), actual (orange).</p>';$span=max(1,$hi-$lo);if(is_finite($lo)){$h.='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 '.max(40,count($entries)*58).'" role="img" aria-label="'.$esc($title).'"><title>'.$esc($title).'</title>';foreach($entries as $i=>$e){$y=58*$i;$h.='<text x="0" y="'.($y+13).'">'.$esc(mb_strimwidth($e['label'],0,24,'…')).'</text>';foreach(['planned'=>'#2563eb','actual'=>'#c2410c'] as $k=>$color){if($e[$k]){[$a,$b]=$e[$k];$x=220+760*($a->getTimestamp()-$lo)/$span;$w=max(1,760*($b->getTimestamp()-$a->getTimestamp())/$span);$h.='<rect x="'.$x.'" y="'.($y+($k==='planned'?2:23)).'" width="'.$w.'" height="15" fill="'.$color.'"/>';}}}$h.='</svg>';}
 $h.='<ul>';foreach($entries as $e){$h.='<li><strong>'.$esc($e['label']).'</strong>';foreach(['planned','actual'] as $k){$h.=' <span>'.$k.': '.($e[$k]?$esc($e[$k][0]->setTimezone($zone)->format(DATE_ATOM).' – '.$e[$k][1]->setTimezone($zone)->format(DATE_ATOM)):'missing').'</span>';}$h.='</li>';}return $h.'</ul>'.(!$entries?'<p>No intervals.</p>':'').'</section>';
}
